+$$('.filter-btn').forEach(b=>b.addEventListener('click',()=>{$$('.filter-btn').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');filter=b.dataset.filter;rosterRender()}));
+function confirmModal(title,body,ok,onOk){const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="eyebrow">MANAGER'S OFFICE</div><h2>${title}</h2><p>${body}</p><div class="modal-actions"><button class="cancel-btn">CANCEL</button><button class="primary-btn confirm-btn">${ok} <span>↗</span></button></div></div></div>`;root.querySelector('.cancel-btn').onclick=()=>root.innerHTML='';root.querySelector('.modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))root.innerHTML=''};root.querySelector('.confirm-btn').onclick=()=>{root.innerHTML='';onOk()}}
+$('#roster-list').addEventListener('click',e=>{const btn=e.target.closest('button[data-action]');if(!btn)return;const p=squad.find(x=>x.name===btn.dataset.name);if(!p)return;const action=btn.dataset.action;
+ if(action==='sell')confirmModal(`Sell ${p.name}?`,`A club has offered ${money(p.value)} for ${p.name}. Accepting will add the fee to your transfer budget and remove the player from your squad.`,'ACCEPT OFFER',()=>{budget+=p.value;squad.splice(squad.indexOf(p),1);updateBudget();rosterRender();showToast(`${p.name} sold for ${money(p.value)}`)});
+ else confirmModal(`Loan out ${p.name}?`,`Send ${p.name} on a season-long loan. You’ll receive a £${Math.max(80,Math.round(p.value*20))}K loan fee and free up a place in the squad.`,'CONFIRM LOAN',()=>{const fee=Math.max(.08,p.value*.02);budget+=fee;squad.splice(squad.indexOf(p),1);updateBudget();rosterRender();showToast(`${p.name} loaned out · +${money(fee)}`)})
+});
+function playerCard(p,mode){const outgoing=mode==='outgoing';const btnText=outgoing?'SELL':'SIGN';const cost=outgoing?money(p.value):mode==='loans'?`${money(p.value)} FEE`:`${money(p.value)}`;return `<article class="market-player"><div class="player-rating">${p.rating}<small>OVR</small></div><div class="roster-name"><b>${p.name}</b><small>${p.role} · ${p.age} yrs</small></div><span class="position-chip">${p.pos}</span><span class="player-nationality">${p.nation}</span><div class="market-value">${cost}<small>${outgoing?'MARKET VALUE':`POT ${p.potential||'—'} · £${(p.wage/1000).toFixed(0)}K/WK`}</small></div><button class="deal-btn" data-name="${p.name}" ${!outgoing&&budget<p.value?'disabled':''}>${outgoing?'SELL':mode==='loans'?'LOAN':'SIGN'} &nbsp;↗</button></article>`}
+function marketRender(){let players=marketMode==='signings'?signings:marketMode==='loans'?loans:squad;const query=$('#market-search').value.trim().toLowerCase();players=players.filter(p=>p.name.toLowerCase().includes(query)||p.role.toLowerCase().includes(query)||p.pos.toLowerCase().includes(query));$('#market-list').innerHTML=players.length?players.map(p=>playerCard(p,marketMode)).join(''):'<div class="empty-state">No players match your search.</div>'}
+$$('.market-tab').forEach(b=>b.addEventListener('click',()=>{$$('.market-tab').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');marketMode=b.dataset.market;$('#market-search').value='';marketRender()}));$('#market-search').addEventListener('input',marketRender);
+$('#market-list').addEventListener('click',e=>{const btn=e.target.closest('.deal-btn');if(!btn)return;const name=btn.dataset.name;let pool=marketMode==='signings'?signings:marketMode==='loans'?loans:squad;const p=pool.find(x=>x.name===name);if(!p)return;
+ if(marketMode==='outgoing'){confirmModal(`Sell ${p.name}?`,`Accept the current market value of ${money(p.value)} and release ${p.name} from your squad.`,'ACCEPT OFFER',()=>{budget+=p.value;squad.splice(squad.indexOf(p),1);updateBudget();rosterRender();marketRender();showToast(`${p.name} sold · +${money(p.value)}`)});return}
+ const loan=marketMode==='loans';const fee=p.value;confirmModal(`${loan?'Loan':'Sign'} ${p.name}?`,`${loan?'Season loan fee':'Transfer fee'}: ${money(fee)}. ${loan?'The player joins your squad until the end of the season.':`${p.name} will join Northstar FC on a permanent deal.`}`,'CONFIRM DEAL',()=>{if(budget<fee){showToast('Not enough transfer budget');return}budget-=fee;const added={...p,value:loan?Math.max(1.5,p.rating*.12):p.value};squad.push(added);pool.splice(pool.indexOf(p),1);updateBudget();rosterRender();marketRender();showToast(`${p.name} ${loan?'joins on loan':'signed'}!`)});
+});
+
 </body>
