const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox']});
  const page = await browser.newPage({viewport: {width: 1365, height: 900}});
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('file:///home/runner/work/PlayGround/PlayGround/index.html');
  const content = async s => page.locator(s).innerText();
  const initialBudget = await content('#budget');
  await page.locator('[data-view="squad"]').click();
  await page.locator('[data-filter="DEF"]').click();
  const defenders = await page.locator('.roster-row').count();
  await page.locator('[data-view="market"]').click();
  await page.locator('[data-market="signings"]').click();
  await page.locator('.deal-btn').first().click();
  await page.locator('.confirm-btn').click();
  const signedBudget = await content('#budget');
  const signedRows = await page.locator('#roster-list .roster-row').count();
  await page.locator('[data-market="loans"]').click();
  await page.locator('.deal-btn').first().click();
  await page.locator('.confirm-btn').click();
  const loanRows = await page.locator('#roster-list .roster-row').count();
  await page.locator('[data-market="outgoing"]').click();
  await page.locator('.deal-btn').first().click();
  await page.locator('.cancel-btn').click();
  const afterCancelRows = await page.locator('#roster-list .roster-row').count();
  await page.locator('[data-view="match"]').click();
  await page.evaluate(() => { Math.random = () => .5; });
  await page.locator('#shoot-btn').click();
  await page.waitForFunction(() => document.querySelector('#kick-label').textContent === 'KICK 2 OF 5', {timeout: 5000});
  const firstResult = await content('#match-message');
  await page.locator('#shoot-btn').click();
  await page.locator('#new-match').click();
  await page.waitForTimeout(1000);
  const restartedLabel = await content('#kick-label');
  const restartedScore = `${await content('#score-home')}:${await content('#score-away')}`;
  for (let i=0; i<5; i++) {
    await page.locator('#shoot-btn').click();
    const expected = i < 4 ? `KICK ${i+2} OF 5` : 'SUDDEN DEATH · KICK 1';
    await page.waitForFunction(text => document.querySelector('#kick-label').textContent === text, expected, {timeout: 5000});
  }
  const suddenDeath = await content('#kick-label');
  const mobile = await browser.newPage({viewport: {width: 390, height: 844}, isMobile: true, hasTouch: true});
  await mobile.goto('file:///home/runner/work/PlayGround/PlayGround/index.html');
  const mobileDims = await mobile.evaluate(() => ({width: innerWidth, doc: document.documentElement.scrollWidth, canvas: document.querySelector('#pitch').getBoundingClientRect().width, button: document.querySelector('#shoot-btn').getBoundingClientRect().toJSON()}));
  await mobile.locator('#shoot-btn').tap();
  const mobileStarted = await mobile.locator('#shoot-btn').isDisabled();
  console.log(JSON.stringify({initialBudget, defenders, signedBudget, signedRows, loanRows, afterCancelRows, firstResult, restartedLabel, restartedScore, suddenDeath, mobileDims, mobileStarted, errors}, null, 2));
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });

